Let $f\in\mathcal{S}(\mathbb{U})$ be such that $f(z)f'(z)/z \neq 0$, $z \in \mathbb U$. Then $f$ is said to be $\alpha$-convex in $\mathbb{U}$ if and only if
\begin{align}\label{Def1}
\Re\left\lbrace J_{\alpha}[f](z)\right\rbrace>0,\quad z\in\mathbb{U},
\end{align}
where
\begin{align*}
J_{\alpha}[f](z)=(1-\alpha)\frac{zf'(z)}{f(z)}+\alpha\left(1+\frac{zf''(z)}{f'(z)}\right).
\end{align*}

\emph{\cite{Todorov-1987}} The function $f\in \mathcal{M}_{\alpha}(\mathbb{U})$ for $\alpha>0$ if and only  if there exists a starlike function $F$ such that
\begin{align}\label{TheoB1}
f(z)=\left\lbrack\frac{1}{\alpha}\int\limits_{0}^{z}F^{1/\alpha}(\xi)\xi^{-1}{\rm d}\xi \right\rbrack^{\alpha}\quad z\in\mathbb{U},
\end{align}
where powers are meant as principal values.

\emph{\cite[Theorem 1]{Sokol-Thomas-2018}} Let $f \in \mathcal{M}_\alpha(\mathbb{U})$, $\alpha \ge 0$, be of the form \eqref{eq1}. Then
\begin{align}\label{TheoD1}
|a_2 a_4 - a_3^2| \le
\begin{cases}
\dfrac{2(1 + 8\alpha + 3\alpha^2)}{(1 + 3\alpha)(2 + 15\alpha + 24\alpha^2 + 7\alpha^3)}, & \text{when } \alpha \in [0, 1], \\[10pt]
\dfrac{3 + 35\alpha + 126\alpha^2 + 162\alpha^3 + 79\alpha^4 + 27\alpha^5}{(1 + 2\alpha)^2 (1 + 3\alpha)(3 + 26\alpha + 42\alpha^2 + 18\alpha^3 + 7\alpha^4)}, & \text{when } \alpha \in [1, \infty).
\end{cases}
\end{align}

\emph{\cite[Theorem 2]{Sokol-Thomas-2018}} Let $f\in \mathcal{S}(\mathbb{U})$, $\alpha\in\mathbb{R}$ and $0\leq \beta\leq 1$. If
\begin{align}\label{TheoE1}
\Re\left\lbrace (1-\alpha)\frac{zf'(z)}{f(z)}+\alpha\left(1+\frac{zf''(z)}{f'(z)}\right)\right\rbrace>\beta,\quad z\in \mathbb{U},
\end{align}	
then
\begin{align}\label{TheoE2}
H_2(2) \le \begin{cases}
(1 - \beta)^2, & \text{if } \alpha = \beta = 0, \\[8pt]
\dfrac{(1 - \beta)^2 (S_1 + S_2)}{(\alpha + \beta)(1 + 3\alpha) S_3}, & \text{if } 0 < \alpha + 2\beta \le 1, \\[12pt]
\dfrac{(1 - \beta)^2 (S_4 + S_5)}{(1 + 2\alpha)^2 (1 + 3\alpha) S_6}, & \text{if } \alpha + 2\beta \ge 1,
\end{cases}
\end{align}
where
\begin{align*}
	S_1 &= 6\alpha^3 + 16\alpha^2 + 2\alpha, \\
	S_2 &= -6\alpha^2\beta + 2\beta - \beta^2 + 12\alpha\beta - 9\alpha\beta^2, \\
	S_3 &= 2 + 15\alpha + 24\alpha^2 + 7\alpha^3 - 10\alpha\beta - \beta - 13\alpha^2\beta, \\
	S_4 &= 3 + 35\alpha + 126\alpha^2 + 162\alpha^3 + 79\alpha^4 + 27\alpha^5, \\
	S_5 &= -4\beta - 52\alpha\beta - 184\alpha^2\beta - 180\alpha^3\beta - 12\alpha^4\beta + 2\beta^2 + 26\alpha\beta^2 + 92\alpha^2\beta^2 + 84\alpha^3\beta^2, \\
	S_6 &= 3 + 26\alpha + 42\alpha^2 + 18\alpha^3 + 7\alpha^4 - 4\beta - 40\alpha\beta - 52\alpha^2\beta + 2\beta^2 + 20\alpha\beta^2 + 26\alpha^2\beta^2.
\end{align*}

\emph{\cite[Definition 1.2]{Hamada-2001}}
Let $f:\mathbb{B}\to {\mathbb X}$ be a normalized locally biholomorphic mapping and let $\beta\in [0,1)$. We say that $f$ is starlike of order $\beta$ if
\begin{align*}
\displaystyle
\Re\left\lbrace \frac{||z||}{l_z([Df(z)]^{-1}f(z))}\right\rbrace>\beta,\quad z\in\mathbb{B}\backslash\{0\},\quad l_z\in T(z).
\end{align*}

\cite[Definition 1,1]{Liu-Liu-2010}
A normalized locally biholomorphic mapping $f\in\mathcal{H}(\mathbb{B})$ is said to be quasi-convex of type $B$ and order $\beta$ if
\begin{align*}
\displaystyle
\Re\left\lbrace \frac{l_z\left([Df(z)]^{-1}\left(D^2f(z)(z,z)+Df(z)z\right)\right)}{||z||}\right\rbrace>\beta,\quad z\in\mathbb{B}\backslash\{0\},\quad l_z\in T(z).
\end{align*}

Let $f:\mathbb{B}\to {\mathbb X}$ be a normalized locally biholomorphic mapping and let $\alpha\in \mathbb{R}$. Then $f$ is said to be $\alpha$-convex in $\mathbb{B}$ if and only if
\begin{align*}
\displaystyle
\Re\left\lbrace (1-\alpha)\frac{||z||}{l_z\left([DF(z)]^{-1}F(z)\right)} +\alpha\frac{l_z\left([DF(z)]^{-1}(D^2 F(z)(z^2)+DF(z) z)\right)}{||z||}\right\rbrace>0,
\end{align*}
$z\in\mathbb{B}\backslash\{0\}$ and $l_z\in T(z)$.

By the given condition, we have $F\in\mathcal{M}_{\alpha}(\mathbb{B})$ and so
\begin{align}\label{Lem1.1}
\displaystyle
\Re\left\lbrace (1-\alpha)\frac{||z||}{l_z\left([DF(z)]^{-1}F(z)\right)} +\alpha\frac{l_z\left([DF(z)]^{-1}\phi(z)\right)}{||z||}\right\rbrace>0,
\end{align}
for $z\in\mathbb{B}\backslash\{0\}$ and $l_z\in T(z)$, where $\phi(z)=D^2 F(z)(z^2)+DF(z) z$.	
	
Let $z\in \mathbb{B}\backslash\{0\}$ be fixed and let $z_0=z/\|z\|$.
We define the function $H:\mathbb{U}\to \mathbb{C}$ as follows
\begin{align}\label{Lem1.2}	
\displaystyle
H(\zeta)=\begin{cases}
(1-\alpha)\frac{\zeta}{l_{z}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}+\alpha \frac{l_{z}\left([DF(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{\zeta},& \zeta\neq 0,\\[8pt]
1& \zeta=0.
\end{cases}
\end{align}

\noindent Clearly $H\in\mathcal{H}(\mathbb{U})$ and $H(0)=1$.
Since $l_{\zeta z}=\frac{|\zeta|}{\zeta}l_z$ for each $\zeta\in\mathbb{U}\backslash\{0\}$, we have
\begin{align}\label{Lem1.3}
   H(\zeta)
   =(1-\alpha)\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}+\alpha \frac{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}
\end{align}	
and so $\Re\{H(\zeta)\}>0$ for all $\zeta\in\mathbb{U}$.
Using a similar method as in Theorem 7.1.14 \cite{Graham-Kohr}, we have
\begin{align}\label{Lem1.4}
\displaystyle
[D F(z)]^{-1}F(z)=\frac{f(z) z}{f(z)+D f(z)z},
\end{align}
where $D f(z):\mathbb B\rightarrow\mathbb C$ because $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$, $D F(z):\mathbb B\rightarrow\mathbb {\mathbb X}$, and
\begin{align}\label{Lem1.5}
\displaystyle
[D F(z)]^{-1}\phi(z)=\frac{\phi(z)}{f(z)+D f(z)z},
\end{align}
where $\phi(z)=D^2 F(z)(z^2)+DF(z) z$. Now from \eqref{Lem1.4}, it is clear that
\begin{align}\label{Lem1.6}
\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}=\frac{f(\zeta z_0)+D f(\zeta z_0)\zeta z_0}{f(\zeta z_0)}.
\end{align}

\noindent Suppose $g(\zeta)=f(\zeta z_0)\zeta$. Then we have
\begin{align}\label{Lem1.7}
g'(\zeta)=f(\zeta z_0)+Df(\zeta z_0)\zeta z_0.
\end{align}

\noindent Since $g(\zeta)=f(\zeta z_0)\zeta$, using \eqref{Lem1.7} to \eqref{Lem1.6}, we get
\begin{align}\label{Lem1.8}
\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}=\zeta\frac{g'(\zeta)}{g(\zeta)}.
\end{align}

\noindent Now we will be trying to express the  part with the function $\phi$ in \eqref{Lem1.3} in terms of the function $g$. As the function $F$ is normalized, it has the power series expansion
\begin{equation}\label{Lem1.9a}
F(z)=z+\sum\limits_{k=2}^{\infty}\frac{1}{k!}D^k F(0)(z^k).
\end{equation}
It is known that
\begin{equation*}
  \frac{1}{k!}D^kF(z)(h^k)=\frac{1}{2\pi i}\int_{|\zeta|=r}\frac{F(z+\zeta h)}{\zeta^{k+1}}{\rm d}\zeta,
\end{equation*}
so
\begin{align*}
  \phi(z)=D^2 F(z)(z^2)+DF(z)(z)=&\frac{1}{2\pi i}\int_{|\zeta|=r}\frac{(2+\zeta)F((1+\zeta)z)}{\zeta^{3}}{\rm d}\zeta.
\end{align*}
\noindent Using \eqref{Lem1.9a} in this integral, we get
\begin{align}\label{Lem1.11}
\displaystyle
\phi(z)=D^2 F(z)(z^2)+DF(z)
(z)=&z+\sum\limits_{k=2}^{\infty}\frac{k^2}{k!}D^k F(0)(z^k).
\end{align}

\noindent Since $F(z)=zf(z)$, we have (see \cite[Theorem 2]{Xiong-Yu-Wang-2025})
\begin{align}\label{Th-1x}
\displaystyle
D^mF(0)(z^m)=mD^{m-1}f(0)(z^{m-1})z,
\end{align}
where $m\in\mathbb{N}$. As $z_0=z/||z||$, $l_{z}=\|z\|$, it follows from \eqref{Th-1x} that
\begin{align}\label{Th-1y}
\displaystyle
\frac{l_{z}(D^mF(0)(z^m))}{m!||z||^m}=\frac{D^{m-1}f(0)(z_0^{m-1})}{(m-1)!}.
\end{align}


\noindent Now substituting \eqref{Th-1x} into \eqref{Lem1.9a} and \eqref{Lem1.11}, we get respectively
\begin{equation}\label{Lem1.12}
\displaystyle
F(z)=z+\sum\limits_{k=2}^{\infty}\frac{k}{k!}D^{k-1} f(0)(z^{k-1}) z
\end{equation}
and
\begin{equation}\label{Lem1.13}
\displaystyle
\phi(z)=D^2 F(z)(z^2)+DF(z)
(z)=z+\sum\limits_{k=2}^{\infty}\frac{k^3}{k!}D^{k-1} f(0)(z^{k-1}) z.
\end{equation}

\noindent Therefore, we have
\begin{align}\label{Lem1.13a}
\displaystyle
\phi(\zeta z_0)=\zeta z_0\left(1+\sum\limits_{m=1}^{\infty}\frac{(m+1)^2}{m!}D^{m} f(0)(z_0^{m})\zeta^m\right).
\end{align}

\noindent If
\begin{align}\label{Lem1.14}
\displaystyle
f(\zeta z_0)=1+\sum\limits_{k=1}^{\infty}\frac{1}{k!}D^k f(0)(z_0^k)\zeta^k,
\end{align}
then
\begin{align}\label{Lem1.15}
\displaystyle
D f(\zeta z_0)(\zeta z_0)=\sum\limits_{k=1}^{\infty}\frac{k}{k!}D^k f(0)(z_0^k)\zeta^k.
\end{align}

\noindent In view of \eqref{Lem1.7} and adding \eqref{Lem1.14} and \eqref{Lem1.15}, we obtain
\begin{align}\label{Lem1.16}
\displaystyle
g'(\zeta)=f(\zeta z_0)+D f(\zeta z_0)\zeta z_0=1+\sum\limits_{k=1}^{\infty}\frac{k+1}{k!}D^k f(0)(z_0^k)\zeta^k.
\end{align}	

\noindent Clearly
\begin{align}\label{Lem1.17}
\displaystyle
\zeta g''(\zeta)+g'(\zeta)=1+\sum\limits_{k=1}^{\infty}\frac{(k+1)^2}{k!}D^k f(0)(z_0^k)\zeta^k.
\end{align}

\noindent Now from \eqref{Lem1.5}, \eqref{Lem1.13a} and \eqref{Lem1.16}, we get
\begin{align}\label{Lem1.18}
\displaystyle
\frac{l_{\zeta z_0}\left([D F(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}=\frac{1+\sum\limits_{m=1}^{\infty}\frac{(m+1)^2}{m!}D^{m} f(0)(z^{m})\zeta^m}{1+\sum\limits_{k=1}^{\infty}\frac{k+1}{k!}D^k f(0)(z_0^k)\zeta^k}.
\end{align}

\noindent Using \eqref{Lem1.16} and \eqref{Lem1.17} to \eqref{Lem1.18}, we express the  second part of \eqref{Lem1.3} in terms of the function $g$
\begin{align}\label{Lem1.19}
\frac{l_{\zeta z_0}\left([D F(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}
	=&\frac{\zeta g''(\zeta)+g'(\zeta)}{g'(\zeta)}=1+\zeta\frac{
	g''(\zeta)}{g'(\zeta)}.
\end{align}

\noindent Now in view of \eqref{Lem1.8} and  \eqref{Lem1.19}, we find that
\begin{align*}\label{Lem1.21}
\Re\{H(\zeta)\}=&\Re\left\{(1-\alpha)\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}+\alpha \frac{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}\right\}\\
        =&\Re\left\{(1-\alpha)\frac{\zeta g'(\zeta)}{g(\zeta)}+\alpha\left\{1+\frac{
	\zeta g''(\zeta)}{g'(\zeta)}\right\}\right\}>0, \quad (\zeta\in\mathbb U).
\end{align*}
Therefore, the function $g$ is $\alpha$-convex function defined in Definition A and so, from Theorem A, we have
\begin{equation*}
  \Re\left\{\frac{\zeta g'(\zeta)}{g(\zeta)}\right\}=\Re\left\{\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}\right\}>0, \quad (\zeta\in\mathbb U)
\end{equation*}
so the equivalence between \eqref{Lem1.2} and \eqref{Lem1.3} implies that $F\in\mathcal{S}^*(\mathbb{B})$. Furthermore, from Theorem A, we have for $\alpha\geq 1$
\begin{equation*}
  \Re\left\{1+\frac{\zeta g''(\zeta)}{g'(\zeta)}\right\}=\Re\left\{\frac{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}\right\}>0, \quad (\zeta\in\mathbb U)
\end{equation*}
So, if $\alpha\geq 1$, then $F\in\mathcal{K}_B(\mathbb{B})$. Furthermore, the observations after Theorem A imply that if $F(z)=zf(z)\in\mathcal{M}_{\beta}(\mathbb{B})$, then $F(z)=zf(z)\in\mathcal{M}_{\alpha}(\mathbb{B})$ for all $\alpha,
 \beta\in\mathbb{R}$, $0\leq \alpha/\beta\leq 1$.

Let $g(z)=\frac{f(l_{u}(z))}{l_{u}(z)}$. Since $f\in\mathcal{S}(\mathbb{U})$, it follows that
\begin{align*}
\frac{f'(l_{u}(z))l_{u}(z)}{f(l_{u}(z))}\neq 0, \quad z\in\mathbb{B}.
\end{align*}
	
\noindent Straightforward calculation yields
\begin{align}\label{Lem2.1}
\frac{Dg(z) z}{g(z)}+1=\frac{f'(l_{u}(z))l_{u}(z)}{f(l_{u}(z))}.
\end{align}	
	
\noindent Clearly $Dg(z) z/g(z)+1\neq 0$ for all $z\in\mathbb{B}$. Using a similar method as in Theorem 7.1.14 \cite{Graham-Kohr}, we have
\begin{align*}
\displaystyle
[D F(z)]^{-1}\eta=\frac{1}{g(z)}\left\lbrack \eta-\frac{(Dg(z)\eta)z}{g(z)+D g(z)z}\right\rbrack,\quad \eta\in {\mathbb X}.
\end{align*}

\noindent Hence, $F$ is a normalized locally biholomorphic on $\mathbb{B}$, and
\begin{align*}
\displaystyle
[D F(z)]^{-1}F(z)=\frac{f(l_{u}(z))}{f'(l_{u}(z))l_{u}(z)}z
\end{align*}
and so
\begin{align}\label{Lem2.2}
\frac{||z||}{l_z\left([D F(z)]^{-1}F(z)\right)}=\frac{f'(l_{u}(z))l_{u}(z)}{f(l_{u}(z))}.
\end{align}

\noindent Since $F(z)=g(z)z$, it follows that $D F(z)\eta=(Dg(z)\eta)z+g(z)\eta$, $\eta\in {\mathbb X}$. Consequently
$D F(z)z=f'(l_u(z))z$. Therefore
\begin{align*}
D^2 F(z)(z^2)+DF(z)z=D(DF(z)z)z=f''(l_u(z))l_u(z)z+f'(l_u(z))z,
\end{align*}
which shows that $D^2 F(z)(z^2)=f''(l_u(z))l_u(z)z$.
Note that
\begin{align*}
&[DF(z)]^{-1}(D^2 F(z)(z^2)+DF(z)z)\\=&z+[DF(z)]^{-1}(D^2 F(z)(z^2))\\=&
z+\frac{1}{g(z)}\left\lbrack f''(l_u(z))l_u(z)z-\frac{Dg(z)z}{g(z)+Dg(z)z}f''(l_u(z))l_u(z)z\right\rbrack, \quad z\in\mathbb{B}
\end{align*}
and so from \eqref{Lem2.1}, we obtain
\begin{align*}
[DF(z)]^{-1}(D^2 F(z)(z^2)+DF(z)z)=\left\lbrack 1+\frac{f''(l_u(z))l_u(z)}{f'(l_u(z))}\right\rbrack z,\quad z\in\mathbb{B}.
\end{align*}

\noindent Clearly
\begin{align}\label{Lem2.3}
\frac{l_z\left([DF(z)]^{-1}(D^2 F(z)(z^2)+DF(z)z)\right)}{||z||}=1+\frac{f''(l_u(z))l_u(z)}{f'(l_u(z))},\quad z\in\mathbb{B}.
\end{align}

\noindent Now from \eqref{Lem2.2} and \eqref{Lem2.3}, we see that
\begin{align*}
&\Re\left\lbrace (1-\alpha)\frac{||z||}{l_z\left([DF(z)]^{-1}F(z)\right)} +\alpha\frac{l_z\left([DF(z)]^{-1}(D^2 F(z)(z^2)+DF(z)z)\right)}{||z||}\right\rbrace\\=&\Re\left\lbrace (1-\alpha)\frac{f'(l_{u}(z))l_{u}(z)}{f(l_{u}(z))}+\alpha\left(1+\frac{f''(l_u(z))l_u(z)}{f'(l_u(z))}\right)\right\rbrace>0
\end{align*}	
if and only if
\begin{align*}
\Re\left\lbrace (1-\alpha)\frac{\xi f'(\xi)}{f(\xi)}+\alpha\left(1+\frac{\xi f''(\xi)}{f'(\xi)}\right)\right\rbrace>0, \quad \xi\in\mathbb{U}.
\end{align*}
This shows that
$F(z)=\frac{f(l_{u}(z))}{l_{u}(z)}z$ belongs to $\mathcal{M}_{\alpha}(\mathbb{B})$ if and only if $f \in \mathcal{M}_{\alpha}(\mathbb{U})$.

First we suppose that $F\in\mathcal{M}_{\alpha}(\mathbb{B})$. Clearly $F$ is biholomorphic on $\mathbb{B}$. Since $F(z)=f(z)z$, it follows that $D F(z)z=(Df(z)z)z+f(z)z$, $z\in \mathbb{B}$. Thus $f(z)\neq 0$ and $f(z)+Df(z)z\neq 0$ for all $z\in\mathbb{B}$. Since $g(\zeta)=f(\zeta z_0)\zeta$, we using \eqref{Lem1.8}, we get
\begin{align}\label{Lem3.1}
\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)}=\zeta\frac{g'(\zeta)}{g(\zeta)}.
\end{align}

\noindent Let $\phi(z)=D^2 F(z)(z^2)+DF(z)z)$.
On the other hand, \eqref{Lem1.19} gives
\begin{align}\label{Lem3.2}
\displaystyle
\frac{l_{\zeta z_0}\left([D F(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}
=1+\zeta\frac{
g''(\zeta)}{g'(\zeta)}.
\end{align}

\noindent Therefore, using \eqref{Lem3.1} and \eqref{Lem3.2}, we obtain that
\begin{align*}
&\Re\left\lbrace (1-\alpha)\frac{\zeta g'(\zeta)}{g(\zeta)}+\alpha\left(1+\frac{\zeta g''(\zeta)}{g'(\zeta)}\right)\right\rbrace\\=
&\Re\left\lbrace (1-\alpha)\frac{||\zeta z_0||}{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}F(\zeta z_0)\right)} +\alpha\frac{l_{\zeta z_0}\left([DF(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{||\zeta z_0||}\right\rbrace>0,
\end{align*}
which implies that $g\in\mathcal{M}_{\alpha}(\mathbb{U})$.
\vspace{1.2mm}

\noindent Conversely, we assume $g\in\mathcal{M}_{\alpha}(\mathbb{U})$. Clearly $\frac{\zeta g'(\zeta)}{g(\zeta)}\neq 0$, $\zeta\in\mathbb{U}$. Therefore from \eqref{Lem2.1}, we have
\begin{align*}
\frac{Df(z) z}{f(z)}+1\neq 0, \quad z\in\mathbb{B}.
\end{align*}	

\noindent From this and \eqref{Lem1.4}, we readily deduce that $F$ is locally biholomorphic on $\mathbb{B}$. Let us take $z=\zeta z_0$, where $\zeta=||z||$.
Then from \eqref{Lem3.1} and \eqref{Lem3.2}, we get
\begin{align*}
&\Re\left\lbrace (1-\alpha)\frac{||z||}{l_{z}\left([DF(z)]^{-1}F(z)\right)} +\alpha\frac{l_{z}\left([DF(z)]^{-1}\phi(z)\right)}{||z||}\right\rbrace\\&=
\Re\left\lbrace (1-\alpha)\frac{\zeta g'(\zeta)}{g(\zeta)}+\alpha\left(1+\frac{\zeta g''(\zeta)}{g'(\zeta)}\right)\right\rbrace>0,
\end{align*}
which implies that $F\in\mathcal{M}_{\alpha}(\mathbb{B})$.

\label{Th-2} Let $f \in \mathcal{S}(\mathbb{U})$, $u \in {\mathbb X}$ with $\|u\| = 1$ and $l_{u} \in T(u)$. Then
$F(z)=\frac{f(l_{u}(z))}{l_{u}(z)}z\in\mathcal{M}_{\alpha}(\mathbb{B})$ for $\alpha>0$ if and only if there exists $\tilde F(z)=\frac{\tilde f(l_{u}(z))}{l_{u}(z)}z\in\mathcal{S}^*(\mathbb{B})$, where $\tilde f \in \mathcal{S}(\mathbb{U})$ such that
\begin{align}\label{Th-2.0}
f(l_u(z))=\left\lbrack \frac{1}{\alpha} \int_{0}^{l_u(z)} \tilde f^{1/\alpha}(t) t^{-1}\, {\rm d}t \right\rbrack^{\alpha},
\end{align}
where powers are meant as principal values.

First we suppose $F(z)=\frac{f(l_{u}(z))}{l_{u}(z)}z\in\mathcal{M}_{\alpha}(\mathbb{B})$. Then by Proposition \ref{pro-1}, we have $f\in\mathcal{M}_{\alpha}(\mathbb{U})$.
Now from \eqref{Lem2.2} and \eqref{Lem2.3}, we see that
\begin{align}\label{Th-2.1}
&(1-\alpha)\frac{||z||}{l_z\left([DF(z)]^{-1}F(z)\right)} +\alpha\frac{l_z\left([DF(z)]^{-1}(D^2 F(z)(z^2)+DF(z)z)\right)}{||z||}\\=& (1-\alpha)\frac{f'(l_{u}(z))l_{u}(z)}{f(l_{u}(z))}+\alpha\left(1+\frac{f''(l_u(z))l_u(z)}{f'(l_u(z))}\right)=p(l_{u}(z)),\nonumber
\end{align}	
where $p\in\mathcal{P}$.

\noindent Suppose the function $\tilde F(z)=\frac{\tilde f(l_{u}(z))}{l_{u}(z)}z$ is defined by
\begin{align}\label{Th-2.2}
\frac{\tilde f'(l_{u}(z))l_{u}(z)}{\tilde f(l_{u}(z))}=p(l_u(z)).	
\end{align}

\noindent Clearly $\tilde f\in\mathcal{S}^*(\mathbb{U})$. According to Lemma 2.1 \cite{Xu-He-Xu}, we can say that $\tilde F\in\mathcal{S}^*(\mathbb{B})$.
 Let $\xi=l_{u}(z)$. By using the identity
 \begin{align*}
 \frac{\xi \tilde f'(\xi)}{\tilde f(\xi)}=1+\xi\frac{d}{d\xi} \log \frac{\tilde f(\xi)}{\xi},
 \end{align*}
 we get from \eqref{Th-2.2} that
 \begin{align}\label{Th-2.3}
P(\xi)= \frac{\tilde f(\xi)}{\xi}=\exp\left(\int\limits_{0}^{\xi}\frac{p(t)-1}{t} {\rm d}t\right).
 \end{align}

 \noindent Now using \eqref{Th-2.2} and \eqref{Th-2.3} to \eqref{Th-2.1}, we deduce that
 \begin{align}\label{Th-2.4}
 	\frac{f(\xi)}{\xi}\left\lbrack\frac{\xi f'(\xi)}{f(\xi)}\right\rbrack^{\alpha}=\frac{\tilde f(\xi)}{\xi}=P(\xi).
 \end{align}

\noindent  Making the substitution
