 \end{align}

 \noindent Now from \eqref{Th-2.5} and \eqref{Th-2.6}, we get
 \begin{align*}
 f(\xi)= \left\lbrack \frac{1}{\alpha} \int_{0}^{\xi} P^{1/\alpha}(t) t^{1/\alpha-1}\, {\rm d}t \right\rbrack^{\alpha}=\left\lbrack \frac{1}{\alpha} \int_{0}^{\xi} \tilde f^{1/\alpha}(t) t^{-1}\, {\rm d}t \right\rbrack^{\alpha}.
